insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000031', 'terms', 'static', 'الشروط والأحكام', '{"title":"الشروط والأحكام — قواعد الحجز والتنفيذ والدفع","description":"شروط استخدام خدمات النقل: صفة الشركة كوسيط ينفذ عبر متعهدين معتمدين، وقواعد الحجز والتسعير والتحويل ومواعيد الانتظار وحدود المسؤولية والقانون المطبق."}'::jsonb, true, 31)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000003101', 'a0000000-0000-4000-8000-000000000031', 'page-hero', '{"title":"الشروط والأحكام","sub":"القواعد المنظِّمة للعلاقة بينك وبين الشركة في كل حجز — اقرأها قبل تأكيد رحلتك، فتأكيد الحجز يعني موافقتك عليها."}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000003102', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"١. صفة الشركة ونطاق الخدمة","body":"الشركة وسيط لخدمات النقل السياحي البري داخل جمهورية مصر العربية: تتلقى طلبك، وتسعّر رحلتك، وتنظمها، ثم تُنفَّذ الرحلة عبر شبكة من المتعهدين المعتمدين لديها ومن السائقين العاملين معهم. أي سيارة تصلك قد تكون مملوكة للشركة أو لأحد متعهديها المعتمدين، وفي الحالتين تظل الشركة هي الجهة المسؤولة أمامك عن الحجز الذي أكدته معها.\n\nتشمل الخدمة استقبال المطارات، والتنقل داخل المدن، والسفر بين المحافظات، والجولات السياحية، والمناسبات والمؤتمرات. ولا تشمل تأجير السيارة بلا سائق، ولا خدمات الإرشاد السياحي أو تذاكر دخول المزارات أو الحجوزات الفندقية أو تأشيرات السفر، ما لم يُذكر خلاف ذلك كتابةً في تأكيد الحجز.\n\nتطبَّق هذه الشروط على كل طلب أو حجز يتم عبر الموقع أو عبر قنوات التواصل المعلنة، وعلى كل من يستخدم الخدمة سواء أكان هو صاحب الحجز أم راكباً ضمنه."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000003103', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٢. مراحل الحجز ومتى يصبح مؤكداً","body":"يمر الحجز بأربع مراحل: طلب تحدد فيه بيانات رحلتك، ثم عرض سعر بفئات السيارات المتاحة، ثم تحويل المبلغ المطلوب ورفع صورة الإيصال، ثم مراجعة الإيصال من فريق الشركة وإصدار التأكيد.\n\nالحجز لا يُعد مؤكداً بمجرد إرسال الطلب أو إتمام التحويل، وإنما بعد مراجعة الإيصال ووصول رسالة التأكيد إليك على الرقم المسجل في الحجز. ما قبل ذلك يبقى الطلب قيد المراجعة، وقد يتعذر تنفيذه في المواعيد شديدة الازدحام إذا نفدت السيارات المتاحة — وفي هذه الحالة يُرد إليك المبلغ كاملاً.\n\nلكل حجز مؤكد رقم ورابط حالة خاص به، ومن خلاله تتابع مراحل حجزك وترفع إيصال التحويل وتطلب تعديلاً أو إلغاءً. حافظ على هذا الرابط ولا تشاركه مع غير المعنيين بالرحلة."}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000003104', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٣. التسعير والتحويل","body":"جميع الأسعار بالجنيه المصري وتشمل السيارة والسائق والوقود، وتُحتسب على أساس المسافة وفئة السيارة وطبيعة الرحلة (ذهاب فقط أو ذهاب وعودة) وساعات الانتظار المطلوبة، مع أي زيادة معلنة في مواسم الذروة. السعر الذي يظهر لك قبل التأكيد هو السعر النهائي للخدمة المتفق عليها، ولا يُضاف إليه شيء إلا مقابل خدمة إضافية تطلبها بعد التأكيد.\n\nلا تشمل الأسعار — ما لم يُنص على خلاف ذلك — رسوم الطرق ومواقف الانتظار والمعديات وتصاريح دخول بعض المناطق وتذاكر المزارات، وتُسدَّد هذه المبالغ عند استحقاقها الفعلي.\n\nالدفع يتم بالتحويل اليدوي إلى إحدى المحافظ الإلكترونية أو حسابات إنستاباي المعروضة لك في صفحة الدفع الخاصة بحجزك، ثم ترفع صورة واضحة من إيصال التحويل. لا تُقبل التحويلات إلى أي حساب لم يُعرض عليك داخل صفحة حجزك، ولا تتحمل الشركة أي مسؤولية عن مبلغ يُحوَّل إلى حساب من خارج تلك الصفحة أياً كان مصدره. رسوم التحويل التي يفرضها مزود الخدمة المالية يتحملها الطرف الذي يجري التحويل.\n\nقد تُطلب عربوناً أو المبلغ كاملاً بحسب نوع الرحلة وموعدها، ويوضَّح ذلك قبل التحويل. المبلغ المتبقي — إن وُجد — يُسدَّد قبل بدء الرحلة أو للسائق عند التحرك بحسب ما يُتفق عليه في التأكيد."}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000003105', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٤. التزامات الشركة","body":"تلتزم الشركة بتوفير سيارة من الفئة المحجوزة أو من فئة أعلى دون فرق سعر، نظيفة وصالحة للسير ومزودة بتكييف عامل، يقودها سائق يحمل رخصة سارية ويعرف مسار الرحلة.\n\nوتلتزم بإرسال بيانات السائق والسيارة قبل موعد التحرك بوقت كافٍ، وبإبلاغك فور حدوث أي تغيير يمس موعد الرحلة أو السيارة أو السائق، وبتوفير بديل في أقرب وقت ممكن إذا تعطلت السيارة أثناء الرحلة أو قبلها.\n\nكما تلتزم بالتعامل مع بياناتك وفق سياسة الخصوصية المنشورة، وبعدم استخدام بيانات رحلتك لغير غرض تنفيذها ودعمها."}'::jsonb, 4, true),
  ('b0000000-0000-4000-8000-000000003106', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٥. التزامات العميل","body":"تلتزم بتقديم بيانات صحيحة وكاملة: الاسم ورقم هاتف عامل يمكن الوصول إليه وقت الرحلة، وعنوان انطلاق ووجهة دقيقين، وعدد الركاب والحقائب الحقيقي. زيادة العدد عن المحجوز قد تستلزم فئة سيارة أعلى بفرق سعر، وللشركة الاعتذار عن التنفيذ إذا تعذر ذلك في حينه.\n\nوتلتزم بالتواجد في نقطة الانطلاق في الموعد المتفق عليه، وباحترام السائق وتعليمات السلامة، وبعدم التدخين داخل السيارة، وبعدم نقل أي مواد ممنوعة قانوناً أو خطرة. ويُمنع تحرك السيارة بعدد ركاب يتجاوز طاقتها المرخصة أو بدون ربط أحزمة الأمان.\n\nأنت مسؤول عن أي تلف يلحق بالسيارة بفعل متعمد أو إهمال جسيم منك أو من مرافقيك، وعن الغرامات المترتبة على مخالفتك أنت للقانون أثناء الرحلة.\n\nوأخيراً، الاتفاق المباشر مع السائق على خدمة إضافية أو على سعر خارج المنصة يقع على مسؤوليتك وحدك ولا تلتزم به الشركة ولا تضمنه."}'::jsonb, 5, true),
  ('b0000000-0000-4000-8000-000000003107', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٦. مواعيد الانتظار والتأخير","body":"يشمل كل حجز فترة انتظار مجانية: ١٥ دقيقة للمشاوير داخل المدينة، و٣٠ دقيقة للرحلات بين المحافظات، و٦٠ دقيقة لاستقبال المطارات تُحسب من لحظة الهبوط الفعلي للطائرة لا من الموعد المجدول، لأن الشركة تتابع حالة الرحلة الجوية.\n\nبعد انقضاء الفترة المجانية تُحتسب رسوم انتظار بسعر ساعة الانتظار المعلن لفئة السيارة، وكل ثلاثين دقيقة مبدوءة تُحسب نصف ساعة. وإذا لم يحضر العميل ولم يتواصل خلال ٩٠ دقيقة من الموعد المتفق عليه، تُعتبر الرحلة منفَّذة ولا يُستحق عنها استرداد.\n\nوفي المقابل: إذا تأخرت السيارة عن موعد التحرك أكثر من ٣٠ دقيقة لسبب راجع إلى الشركة أو متعهدها، فلك الاختيار بين خصم يُتفق عليه على قيمة الرحلة أو إلغائها مجاناً واسترداد كامل المبلغ وفق سياسة الاسترداد.\n\nالتأخير الناتج عن الزحام غير المعتاد أو إغلاق الطرق أو الأحوال الجوية أو نقاط التفتيش لا يُعد تأخيراً من الشركة، وتبذل الشركة وسعها لإبلاغك أولاً بأول واقتراح البديل."}'::jsonb, 6, true),
  ('b0000000-0000-4000-8000-000000003108', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٧. التعديل والإلغاء","body":"تعديل موعد الرحلة أو نقاط الانطلاق والوجهة متاح مجاناً قبل موعد التحرك بأربع وعشرين ساعة على الأقل ووفق توفر السيارات، وأي تعديل يزيد المسافة أو ساعات الانتظار أو يرفع فئة السيارة يترتب عليه فرق سعر يُسدَّد قبل التنفيذ.\n\nقواعد الإلغاء ونسب الاسترداد ومدد رد الأموال موضحة بالتفصيل في صفحة سياسة الاسترداد، وهي جزء لا يتجزأ من هذه الشروط.\n\nوللشركة أن تلغي الحجز أو ترفض تنفيذه — مع رد كامل المبلغ — في حالات محددة: تعذر التنفيذ لظرف قاهر، أو ثبوت بيانات غير صحيحة في الطلب، أو وجود ما يهدد سلامة السائق أو المركبة، أو مخالفة الغرض من الرحلة للقانون."}'::jsonb, 7, true),
  ('b0000000-0000-4000-8000-000000003109', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٨. حدود المسؤولية","body":"تلتزم الشركة ببذل عناية الوسيط المحترف في اختيار متعهديها ومتابعة تنفيذ رحلتك، وتظل مسؤولة أمامك عن حسن تنفيذ الخدمة التي أكدتها معك.\n\nولا تُسأل الشركة عن الأضرار غير المباشرة أو التبعية، ومنها على سبيل المثال فوات رحلة جوية أو موعد أو مناسبة، ما لم يثبت أن التأخير راجع إلى خطأ منها أو من متعهدها. كذلك لا تُسأل عن التأخير أو التوقف الناتج عن أحوال الطرق أو الطقس أو الإغلاقات الرسمية أو نقاط التفتيش أو أي قوة قاهرة خارجة عن إرادتها.\n\nالأمتعة والمتعلقات الشخصية في مسؤولية صاحبها طوال الرحلة، وتبذل الشركة جهدها في البحث عما يُنسى داخل السيارة وإعادته إليه دون التزام بضمان ذلك. أما إصابات الركاب في حوادث المرور فتخضع لوثيقة تأمين المركبة النافذة قانوناً وللقواعد المقررة في قوانين المرور المصرية.\n\nوفي جميع الأحوال لا يجاوز الحد الأقصى لتعويض الشركة عن أي مطالبة تتعلق بحجز بعينه قيمة المبلغ المدفوع فعلاً عن ذلك الحجز."}'::jsonb, 8, true),
  ('b0000000-0000-4000-8000-000000003110', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"٩. القانون المطبق وتسوية النزاعات","body":"تخضع هذه الشروط وكل ما ينشأ عنها لأحكام قوانين جمهورية مصر العربية.\n\nإذا كان لديك اعتراض على تنفيذ رحلة، فقدّم شكواك عبر قنوات التواصل المعلنة خلال أربعة عشر يوماً من تاريخ الرحلة مرفقاً بها رقم الحجز، وتلتزم الشركة بالرد خلال سبعة أيام عمل والسعي لتسوية ودية خلال ثلاثين يوماً.\n\nوإذا تعذرت التسوية الودية، تختص المحاكم المصرية المختصة بنظر النزاع. والنص العربي لهذه الشروط هو المرجع المعتمد عند أي اختلاف في الترجمة."}'::jsonb, 9, true),
  ('b0000000-0000-4000-8000-000000003111', 'a0000000-0000-4000-8000-000000000031', 'rich-text', '{"title":"١٠. تعديل هذه الشروط","body":"قد تُحدَّث هذه الشروط من حين لآخر لمواكبة تطور الخدمة أو تغير المتطلبات القانونية، وتُنشر النسخة المحدَّثة على هذه الصفحة فور اعتمادها.\n\nالشروط السارية على حجزك هي المنشورة هنا وقت تأكيده، ولا تسري أي تعديلات لاحقة بأثر رجعي على حجز مؤكد. ولأي استفسار حول بند من هذه البنود، تواصل معنا عبر القنوات المعلنة في صفحة التواصل."}'::jsonb, 10, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000032', 'refund-policy', 'static', 'سياسة الاسترداد', '{"title":"سياسة الاسترداد — الإلغاء ورد الأموال","description":"قواعد إلغاء الحجز واسترداد المبالغ المحوَّلة: نافذة الإلغاء المجاني، وخصومات الإلغاء المتأخر، وحالات الاسترداد الكامل، ومدة رد الأموال وآلية تقديم الطلب."}'::jsonb, true, 32)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000003201', 'a0000000-0000-4000-8000-000000000032', 'page-hero', '{"title":"سياسة الاسترداد","sub":"متى يكون الإلغاء مجانياً، وكم يُخصم عند الإلغاء المتأخر، وكيف ومتى تعود أموالك إلى محفظتك أو حسابك."}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000003202', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"١. نافذة الإلغاء المجاني","body":"يمكنك إلغاء حجزك دون أي خصم واسترداد ١٠٠٪ من المبلغ المحوَّل ضمن المهل التالية، محسوبة من موعد التحرك المتفق عليه:\n\nقبل ٢٤ ساعة على الأقل لمشاوير المدينة واستقبال المطارات. وقبل ٤٨ ساعة على الأقل للرحلات بين المحافظات والجولات السياحية. وقبل ٧٢ ساعة على الأقل لحجوزات المناسبات والمؤتمرات والأفواج التي تتطلب حجز أكثر من سيارة.\n\nالإلغاء داخل هذه النوافذ لا يحتاج تبريراً، ويُسجَّل من رابط حالة الحجز أو عبر قنوات التواصل المعلنة."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000003203', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٢. خصومات الإلغاء المتأخر","body":"بعد انقضاء نافذة الإلغاء المجاني تُطبَّق الخصومات التالية، لأن السيارة تكون قد حُجزت لك وحُرمت من رحلات أخرى:\n\nللرحلات الفردية (مدينة أو مطار أو بين المحافظات): إلغاء قبل الموعد بمدة من ٢٤ إلى ١٢ ساعة يُخصم منه ٢٥٪، ومن ١٢ إلى ٤ ساعات يُخصم منه ٥٠٪، وأقل من ٤ ساعات أو بعد تحرك السائق فعلاً إلى نقطة الانطلاق لا يُستحق عنه استرداد.\n\nللمناسبات والمؤتمرات والأفواج: إلغاء قبل الموعد بمدة من ٧٢ إلى ٤٨ ساعة يُخصم منه ٢٥٪، ومن ٤٨ إلى ٢٤ ساعة يُخصم منه ٥٠٪، وأقل من ٢٤ ساعة لا يُستحق عنه استرداد.\n\nعدم حضور العميل في نقطة الانطلاق وعدم تواصله خلال ٩٠ دقيقة من الموعد يُعامل معاملة الرحلة المنفَّذة، فلا يُستحق عنه استرداد. أما تقصير مدة الرحلة أو إسقاط بعض محطاتها بعد بدئها بناءً على رغبتك فلا يترتب عليه رد جزئي."}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000003204', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٣. حالات الاسترداد الكامل مهما كان التوقيت","body":"تُرد إليك قيمة الحجز كاملة — وبصرف النظر عن موعد الإلغاء — في الحالات التالية: عدم وصول السيارة إلى نقطة الانطلاق، أو تأخرها أكثر من ٤٥ دقيقة لسبب راجع إلى الشركة أو متعهدها، أو وصول سيارة من فئة أدنى من المحجوزة ورفضك لها، أو إلغاء الشركة للحجز لأي سبب من جانبها، أو تعذر توفير سيارة بديلة خلال وقت معقول بعد عطل.\n\nويُرد المبلغ كاملاً كذلك إذا تعذر تنفيذ الرحلة لظرف قاهر يمنعها عن الطرفين، كإغلاق رسمي للطريق أو حظر للحركة أو أحوال جوية تجعل السفر خطراً.\n\nأما إذا حوَّلت مبلغاً أكبر من المستحق أو تكرر التحويل بالخطأ، فيُرد الفارق كاملاً بمجرد التحقق منه دون أي خصم."}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000003205', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٤. مدة رد الأموال وطريقته","body":"يُرد المبلغ بنفس وسيلة التحويل التي دفعت بها وإلى نفس الحساب أو المحفظة التي جاء منها التحويل — ولا يُرد نقداً ولا إلى حساب طرف ثالث، حمايةً لك وللشركة معاً.\n\nالمدة: حتى ٣ أيام عمل من اعتماد طلب الاسترداد للمحافظ الإلكترونية، وحتى ٧ أيام عمل لتحويلات إنستاباي والحوالات البنكية، وقد تضيف بعض البنوك يوماً أو يومين حتى يظهر المبلغ في حسابك.\n\nرسوم التحويل الخاصة برد المبلغ تتحملها الشركة في حالات الاسترداد الكامل الراجعة إليها (البند ٣)، وتُخصم من المبلغ المردود في حالات الإلغاء الصادر من العميل."}'::jsonb, 4, true),
  ('b0000000-0000-4000-8000-000000003206', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٥. كيف تقدّم طلب الاسترداد؟","body":"ابدأ من رابط حالة حجزك واختر طلب الإلغاء، أو راسلنا عبر قنوات التواصل المعلنة. وفي الحالتين نحتاج منك: رقم الحجز، واسم صاحب الحساب أو المحفظة التي جرى التحويل منها، وصورة إيصال التحويل الأصلي، وسبب الإلغاء باختصار.\n\nيُراجَع الطلب خلال ٢٤ ساعة عمل، ويصلك إشعار بقبوله وبالمبلغ الذي سيُرد وبموعد التنفيذ المتوقع، أو برفضه مع بيان السبب ومرجعه من هذه السياسة.\n\nاحتفظ بإيصال التحويل حتى تمام رد المبلغ، فهو المستند الوحيد الذي تُطابَق به الحوالة في حال حدوث أي لبس."}'::jsonb, 5, true),
  ('b0000000-0000-4000-8000-000000003207', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٦. التأجيل بدل الإلغاء","body":"إذا تغيرت خطتك ولم تُلغِ رحلتك من أصلها، فالتأجيل أوفر لك: يمكنك تأجيل الحجز مرة واحدة مجاناً إذا طلبت ذلك قبل موعد التحرك بأربع وعشرين ساعة على الأقل ووفق توفر السيارات، ويبقى المبلغ المحوَّل رصيداً لحجزك الجديد.\n\nوإذا كان الموعد أو المسار الجديد أعلى سعراً، تُسدد الفارق فقط؛ وإذا كان أقل، يُرد إليك الفارق وفق مواعيد البند ٤."}'::jsonb, 6, true),
  ('b0000000-0000-4000-8000-000000003208', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٧. ما لا يشمله الاسترداد","body":"لا يشمل الاسترداد: الخدمات التي نُفِّذت فعلاً كلياً أو جزئياً، وساعات الانتظار المستحقة قبل الإلغاء، والمصروفات التي دُفعت نيابة عنك بناءً على طلبك مثل تذاكر دخول المزارات ورسوم الطرق والمعديات، والغرامات الناتجة عن مخالفتك للقانون أثناء الرحلة.\n\nكما لا تُرد رسوم التحويل التي اقتطعها مزود الخدمة المالية عند دفعك، لأنها لم تصل إلى الشركة أصلاً."}'::jsonb, 7, true),
  ('b0000000-0000-4000-8000-000000003209', 'a0000000-0000-4000-8000-000000000032', 'rich-text', '{"title":"٨. الاسترداد ودور الشركة كوسيط","body":"الشركة وسيط ينفذ الرحلات عبر متعهدين معتمدين، ومع ذلك فأنت تتعامل معها وحدها في كل ما يخص المال: الاسترداد يتم من الشركة إليك مباشرة، ولن يُطلب منك أبداً مطالبة المتعهد أو السائق باسترداد ما دفعته، ولا يُعتد بأي مبلغ سلّمته لهم خارج القنوات المعلنة في صفحة حجزك.\n\nوتُنشر أي تحديثات على هذه السياسة في هذه الصفحة، ويسري على حجزك ما كان منشوراً وقت تأكيده."}'::jsonb, 8, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000033', 'privacy', 'static', 'سياسة الخصوصية', '{"title":"سياسة الخصوصية — بياناتك وكيف نحميها","description":"ما الذي نجمعه من بيانات ولماذا: الاسم والهاتف ونقاط الرحلة وإيصال التحويل، ومن يطّلع عليها ومدة الاحتفاظ بها وحقوقك في الوصول والتصحيح والحذف."}'::jsonb, true, 33)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000003301', 'a0000000-0000-4000-8000-000000000033', 'page-hero', '{"title":"سياسة الخصوصية","sub":"بياناتك أمانة: هنا تعرف بالضبط ما الذي نجمعه، ولماذا، ومن يطّلع عليه، وكم يبقى لدينا، وكيف تطلب حذفه."}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000003302', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"١. من نحن وما الذي تغطيه هذه السياسة","body":"الشركة وسيط لخدمات النقل السياحي داخل جمهورية مصر العربية، تنظم رحلاتك وتنفذها عبر شبكة من المتعهدين المعتمدين. وهي الجهة المسؤولة عن البيانات التي تقدمها لها والمتحكمة في معالجتها.\n\nتغطي هذه السياسة البيانات التي نجمعها من الموقع وصفحات الحجز ونماذج طلب عرض السعر ومراسلاتك معنا على قنوات التواصل المعلنة، وتُقرأ مع الشروط والأحكام باعتبارهما وثيقة واحدة."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000003303', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٢. البيانات التي نجمعها","body":"بيانات التواصل: اسمك ورقم هاتفك أو واتساب، وبريدك الإلكتروني إن أدخلته.\n\nبيانات الرحلة: عنوان نقطة الانطلاق والوجهة وإحداثياتهما التقريبية اللازمة لحساب المسافة، وموعد التحرك، وعدد الركاب والحقائب، وفئة السيارة، ورقم الرحلة الجوية وموعدها في حجوزات المطارات، وأي ملاحظات تكتبها في الطلب.\n\nبيانات الدفع: صورة إيصال التحويل التي ترفعها، وما تحمله من اسم المُرسِل وقيمة الحوالة وتاريخها والأرقام الظاهرة للمحفظة أو الحساب المُرسِل. نحن لا نستقبل بيانات بطاقات بنكية إطلاقاً — لا رقم بطاقة ولا رقماً سرياً ولا رمز تحقق، ولن يطلب منك أي موظف باسم الشركة شيئاً من ذلك، فإن طُلب منك فهي محاولة احتيال ونرجو إبلاغنا فوراً.\n\nبيانات تقنية: عنوان الشبكة (IP) ونوع الجهاز والمتصفح والصفحات التي زرتها داخل الموقع، وتُستخدم مجمَّعة لقياس الأداء وحماية الموقع من الإساءة."}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000003304', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٣. لماذا نجمع هذه البيانات","body":"لتنفيذ ما طلبته: تسعير الرحلة وإصدار الحجز وتخصيص السيارة والسائق ومتابعة التنفيذ حتى الوصول.\n\nلمطابقة التحويل بالحجز والتحقق من سداده وإصدار ما يلزم من مستندات مالية وضريبية.\n\nلإرسال إشعارات الحالة إليك: تأكيد الحجز وبيانات السائق وتذكير الموعد وأي تغيير طارئ.\n\nللدعم والشكاوى وتوثيق ما يجري بشأنها، وللالتزام بما تفرضه القوانين المصرية السارية على الشركة، ولتحسين الخدمة عبر إحصاءات مجمَّعة لا تُعرّف بشخصك.\n\nلا نستخدم بياناتك في رسائل تسويقية إلا بموافقتك، ويمكنك سحب هذه الموافقة في أي وقت."}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000003305', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٤. من يطّلع على بياناتك","body":"فريق الشركة المخوَّل فقط، وبحسب حاجة كل موظف لأداء عمله.\n\nالمتعهد المعتمد المكلَّف بالتنفيذ والسائق المخصص لرحلتك، ويصلهما الحد الأدنى اللازم للتنفيذ: اسمك ورقم هاتفك ونقطتا الانطلاق والوجهة وموعد التحرك وعدد الركاب — دون إيصال التحويل ولا بيانات رحلاتك الأخرى.\n\nمزودو الخدمات التقنية الذين يشغّلون الموقع وقاعدة البيانات وخدمات الخرائط لحساب المسافات وقنوات إرسال الإشعارات، بصفتهم معالجين نيابة عنا وبقدر ما تستلزمه الخدمة.\n\nالجهات الرسمية إذا طلبت ذلك بموجب القانون أو أمر قضائي.\n\nونؤكد صراحة: لا نبيع بياناتك ولا نؤجّرها ولا نتبادلها مع أي طرف ثالث لأغراض تسويقية أو إعلانية، في أي حال من الأحوال."}'::jsonb, 4, true),
  ('b0000000-0000-4000-8000-000000003306', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٥. مدة الاحتفاظ بالبيانات","body":"بيانات الحجوزات المنفَّذة والمستندات المالية المرتبطة بها: خمس سنوات، التزاماً بمتطلبات الدفاتر والسجلات الضريبية.\n\nصور إيصالات التحويل: أربعة وعشرون شهراً من تاريخ الرحلة، ثم تُحذف ما لم تكن محل نزاع أو مطالبة قائمة.\n\nطلبات عروض الأسعار التي لم تكتمل: اثنا عشر شهراً. سجلات المراسلة والدعم: أربعة وعشرون شهراً. السجلات التقنية: اثنا عشر شهراً.\n\nوبعد انقضاء المدة تُحذف البيانات أو تُجهَّل بحيث لا تعود تدل على شخصك."}'::jsonb, 5, true),
  ('b0000000-0000-4000-8000-000000003307', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٦. كيف نحمي بياناتك","body":"الاتصال بالموقع مشفَّر، والوصول إلى لوحة التحكم محصور في حسابات مصرَّح لها بكلمات مرور خاصة.\n\nإيصالات التحويل تُحفظ في مساحة تخزين خاصة غير متاحة للعامة، ولا تُفتح إلا من حساب إداري عبر رابط مؤقت ينتهي بعد دقائق — فلا يمكن الوصول إليها بمعرفة الرابط أو تخمينه.\n\nومع ذلك لا يخلو أي نظام على الإنترنت من مخاطر، ونحن نلتزم بإبلاغك دون تأخير إذا وقع اختراق يمس بياناتك الشخصية بصورة جوهرية."}'::jsonb, 6, true),
  ('b0000000-0000-4000-8000-000000003308', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٧. حقوقك","body":"لك أن تطلب نسخة من بياناتك لدينا، وأن تصحح أي بيان غير دقيق، وأن تطلب حذف بياناتك، وأن تعترض على معالجة معينة أو تسحب موافقتك على الرسائل الترويجية.\n\nلتقديم الطلب راسلنا من رقم الهاتف أو البريد المسجل في حجزك عبر قنوات التواصل المعلنة، وقد نطلب ما يثبت ملكيتك للرقم حمايةً لك من انتحال الصفة. ونرد على طلبك خلال ثلاثين يوماً.\n\nملاحظة: الحذف لا يشمل ما يلزمنا القانون بحفظه — كالمستندات المالية للحجوزات المنفَّذة — وتبقى هذه محفوظة للمدة القانونية ثم تُحذف."}'::jsonb, 7, true),
  ('b0000000-0000-4000-8000-000000003309', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٨. ملفات تعريف الارتباط والتحليلات","body":"نستخدم ملفات تعريف ارتباط أساسية لا يعمل الموقع بدونها: حفظ تفضيلاتك أثناء تصفح صفحات الحجز، وجلسة الدخول للوحة التحكم.\n\nوقد نستخدم أدوات قياس تعطينا إحصاءات مجمَّعة عن عدد الزيارات والصفحات الأكثر مشاهدة ومصادر الزيارة، دون أن تُعرّفنا بشخصك.\n\nلا نستخدم ملفات إعلانية تتعقبك عبر مواقع أخرى دون موافقتك. ويمكنك حذف ملفات تعريف الارتباط أو حظرها من إعدادات متصفحك، مع ملاحظة أن حظر الملفات الأساسية قد يعطّل بعض وظائف الحجز."}'::jsonb, 8, true),
  ('b0000000-0000-4000-8000-000000003310', 'a0000000-0000-4000-8000-000000000033', 'rich-text', '{"title":"٩. بيانات الأطفال وتحديث السياسة","body":"الخدمة موجهة لمن أتم الثامنة عشرة، ولا نجمع بيانات الأطفال قصداً. وحجز رحلة يرافق فيها أطفال يتم عبر وليّ أمرهم، ولا نطلب من الطفل أي بيانات مباشرة.\n\nقد تُحدَّث هذه السياسة كلما تغيرت الخدمة أو المتطلبات القانونية، وتُنشر النسخة المحدَّثة هنا مع سريانها من تاريخ نشرها. ولأي سؤال أو طلب يخص خصوصيتك، تواصل معنا عبر القنوات المعلنة في صفحة التواصل."}'::jsonb, 9, true)
insert into public.site_settings (key, value) values
  ('maintenance', '{"enabled":false,"message":"نجري تحديثاً قصيراً على الموقع لتحسين تجربة الحجز، ونعود بعد وقت قصير بإذن الله. لحجز عاجل أو استفسار، تواصل معنا مباشرة عبر واتساب أو الهاتف.","allowAdmin":true}'::jsonb)
